class Solution {
public:
    bool canAliceWin(int n) {
        long long disc = 441LL - 8LL * n;
        long long s = (long long)sqrt((double)disc);
        while (s * s > disc) s--;
        while ((s + 1) * (s + 1) <= disc) s++;
        long long m = (21 - s) / 2;
        return m % 2 == 1;
    }
};

